/* ===== REVEAL + COUNTERS ===== */
const io=new IntersectionObserver((es)=>{es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}})},{threshold:.12});
document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
const cio=new IntersectionObserver((es)=>{es.forEach(e=>{if(e.isIntersecting){animCount(e.target);cio.unobserve(e.target);}})},{threshold:.4});
document.querySelectorAll('.counter b').forEach(el=>cio.observe(el));
function animCount(el){const t=+el.dataset.count,p=el.dataset.prefix||"";let n=0,step=Math.max(1,Math.floor(t/60));const f=()=>{n+=step;if(n>=t){n=t;}el.textContent=p+n.toLocaleString('es-AR');if(n<t)requestAnimationFrame(f);};f();}

/* ===== HERO SLIDESHOW + VIDEO ===== */
const slides=[...document.querySelectorAll('#heroBg .hero-slide')];let hi=0;
const dw=document.getElementById('heroDots');
slides.forEach((_,i)=>{const d=document.createElement('button');d.className='hdot'+(i===0?' on':'');d.onclick=()=>goS(i);dw.appendChild(d);});
const hd=[...document.querySelectorAll('.hdot')];
function goS(i){slides[hi].classList.remove('active');hd[hi].classList.remove('on');hi=i;slides[hi].classList.add('active');hd[hi].classList.add('on');}
setInterval(()=>goS((hi+1)%slides.length),5200);
function openVideo(){const m=document.getElementById('vmodal');m.classList.add('open');const v=document.getElementById('bemVideo');try{v.play()}catch(e){}}
function closeVideo(e){if(e&&e.target&&e.target.id!=='vmodal'&&!e.target.classList.contains('vclose'))return;document.getElementById('vmodal').classList.remove('open');document.getElementById('bemVideo').pause();}

