const tt=document.getElementById('testiTrack'),td=document.getElementById('testiDots');
TESTI.forEach((t,i)=>{const c=document.createElement('div');c.className='testi-card'+(i===0?' on':'');c.innerHTML=`<div class="stars">★★★★★</div><p>"${t[0]}"</p><div class="who">— ${t[1]}</div>`;tt.appendChild(c);const d=document.createElement('button');d.className='tdot'+(i===0?' on':'');d.onclick=()=>goT(i);td.appendChild(d);});
let ti=0;const tc=[...tt.children],tdo=[...td.children];
function goT(i){tc[ti].classList.remove('on');tdo[ti].classList.remove('on');ti=i;tc[ti].classList.add('on');tdo[ti].classList.add('on');}
setInterval(()=>goT((ti+1)%TESTI.length),5000);

