/* ===== WINE MAP ===== */
let mapMode="wine",curRegion="lujan",actFilter="todas";
const regions=document.querySelectorAll('.region'),stops=document.querySelectorAll('.stop'),route=document.getElementById('route'),legend=document.getElementById('legend'),infoPanel=document.getElementById('infoPanel');
function renderRegion(k){curRegion=k;regions.forEach(g=>g.classList.toggle('sel',g.dataset.region===k));const r=REGIONS[k];let bd=r.bd;if(actFilter!=="todas")bd=bd.filter(b=>b[2].includes(actFilter));
  infoPanel.innerHTML=`<div class="tag" data-i18n="info_zona">Zona del vino</div><h3>${r.name}</h3><div class="meta">${r.chips.map(c=>`<span class="chip">${c}</span>`).join('')}</div><p class="desc" style="margin-top:12px">${r.desc}</p><div class="sub"><span data-i18n="info_bodegas">Bodegas</span>${actFilter!=="todas"?' · '+actFilter:''}</div>`+
  (bd.length?`<ul class="bd-list">${bd.map((b,ix)=>`<li onclick="bodInfo('${k}',${ix})" style="cursor:pointer"><span class="pin"></span><span><b>${b[0]}</b>${b[1]?`<small>${b[1]}</small>`:``}<span class="bdtags">${b[2].map(t=>`<span>${t}</span>`).join('')}</span></span></li>`).join('')}</ul><div id="bodDetail" class="bod-detail"></div>`:`<p class="desc">No hay bodegas con esa experiencia en esta zona. Probá otro filtro.</p>`)+
  `<div style="margin-top:18px"><button class="btn btn-primary" onclick="reservar('Tour bodegas — ${r.name}')"><span data-i18n="info_resv">Reservar tour en</span> ${r.name}</button></div>`;}
function altStop(k){var sp=STOPS[k];if(!sp)return;var el=document.getElementById('altInfo');if(!el)return;el.innerHTML='<div class="tag">Alta montaña · Ruta 7</div><h3>'+sp.name+'</h3><div class="alt-meta">'+(sp.alt||'')+'</div><p>'+sp.desc+'</p>';document.querySelectorAll('.astop').forEach(function(g){g.classList.toggle('sel',g.dataset.stop===k);});}
function renderStop(k){stops.forEach(g=>g.classList.toggle('sel',g.dataset.stop===k));const sp=STOPS[k];
  infoPanel.innerHTML=`<div class="tag">Alta montaña · Ruta 7</div><h3>${sp.name}</h3><div class="meta"><span class="chip">Altitud aprox. ${sp.alt}</span></div><p class="desc" style="margin-top:12px">${sp.desc}</p><div class="sub">El circuito</div><ul class="bd-list"><li><span class="pin"></span><span><b>Recorrido</b><small>Mendoza → Potrerillos → Uspallata → Puente del Inca → Aconcagua</small></span></li><li><span class="pin"></span><span><b>Incluye</b><small>Transporte, guía y paradas panorámicas</small></span></li></ul><div style="margin-top:18px"><button class="btn btn-primary" onclick="reservar('Circuito de Alta Montaña')">Reservar circuito</button></div>`;}
function setMode(m){mapMode=m;document.querySelectorAll('#mapToggle button').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));const mt=m==="mountain";route.classList.toggle('show',mt);stops.forEach(x=>x.classList.toggle('show',mt));regions.forEach(r=>{r.classList.toggle('dim',mt);r.classList.remove('sel');});legend.style.display=mt?'none':'flex';document.getElementById('filters').style.display=mt?'none':'flex';
  if(mt){infoPanel.innerHTML=`<div class="tag">Alta montaña</div><h3>Seguí la Ruta 7</h3><p class="desc" style="margin-top:10px">Desde la ciudad hasta el Aconcagua. Tocá cada parada del recorrido.</p><div class="sub">Paradas</div><ul class="bd-list">${Object.values(STOPS).map(sp=>`<li><span class="pin"></span><span><b>${sp.name}</b><small>${sp.alt}</small></span></li>`).join('')}</ul>`;}else{renderRegion(curRegion);}}
document.querySelectorAll('#mapToggle button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
regions.forEach(g=>{const a=()=>{if(mapMode==="wine")renderRegion(g.dataset.region)};g.onclick=a;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();a();}};});
stops.forEach(g=>{const a=()=>{if(mapMode==="mountain")renderStop(g.dataset.stop)};g.onclick=a;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();a();}};});
document.querySelectorAll('#filters button').forEach(b=>b.onclick=()=>{actFilter=b.dataset.f;document.querySelectorAll('#filters button').forEach(x=>x.classList.toggle('active',x===b));renderRegion(curRegion);});

