const cabOut=document.getElementById('cabOut');
function setCab(z){document.querySelectorAll('#cabZonas button').forEach(b=>b.classList.toggle('active',b.dataset.z===z));cabOut.innerHTML=`<b style="color:var(--ink)">${z}:</b> ${CAB[z]} <button class="btn btn-ghost" style="margin-left:10px;padding:7px 16px" onclick="reservar('Cabalgata en ${z}')">Reservar</button>`;}
document.querySelectorAll('#cabZonas button').forEach(b=>b.onclick=()=>setCab(b.dataset.z));

