const blogCatsEl=document.getElementById('blogCats'),blogGrid=document.getElementById('blogGrid');
const blogCats=["Todas",...new Set(BLOG.map(b=>b[0]))];let actCat="Todas";
blogCatsEl.innerHTML=blogCats.map((c,i)=>`<button class="${i===0?'active':''}" data-c="${c}">${c}</button>`).join('');
blogCatsEl.querySelectorAll('button').forEach(b=>b.onclick=()=>{actCat=b.dataset.c;blogCatsEl.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));renderBlog();});
function renderBlog(){const list=BLOG.filter(b=>actCat==="Todas"||b[0]===actCat);blogGrid.innerHTML=list.map(b=>`<article class="post"><div class="ph" style="background-image:${b[4]}"><span class="cat">${b[0]}</span></div><div class="pbody"><div class="pmeta">${b[2]} · por ${b[3]}</div><h3>${b[1]}</h3><p>${b[5]}</p><span class="read">Leer más →</span></div></article>`).join('');}

/* ===== ITINERARY ===== */
function buildDays(){const i=document.getElementById('itinIn').value,o=document.getElementById('itinOut').value,box=document.getElementById('itinDays');if(!i||!o){return;}const d1=new Date(i),d2=new Date(o);let n=Math.round((d2-d1)/86400000)+1;if(n<1||isNaN(n)){box.innerHTML='<p style="color:var(--terra)">La fecha de salida debe ser posterior a la de llegada.</p>';return;}if(n>14)n=14;let html='';for(let k=1;k<=n;k++){html+=`<div class="day"><div class="day-head"><span data-i18n="dia">Día</span> ${k}</div><div class="day-body">${sel('bodegas','Bodega',k)}${sel('excursiones','Excursión',k)}${sel('restaurantes','Restaurante',k)}${sel('traslados','Traslado',k)}</div></div>`;}box.innerHTML=html;updateItin();box.querySelectorAll('select').forEach(s=>s.onchange=updateItin);applyLang(window.LANG||'es');}
function sel(key,label,day){const ik={bodegas:'it_bodega',excursiones:'it_excursion',restaurantes:'it_restaurante',traslados:'it_traslado'}[key];return `<div class="pick"><label data-i18n="${ik}">${label}</label><select data-day="${day}" data-k="${key}">${ITIN[key].map(o=>`<option>${o}</option>`).join('')}</select></div>`;}
function updateItin(){const sels=[...document.querySelectorAll('#itinDays select')];const pax=document.getElementById('itinPax').value||1;let any=false,txt=`Pasajeros: ${pax}\n`;const byDay={};sels.forEach(s=>{if(s.value!=="—"){any=true;byDay[s.dataset.day]=byDay[s.dataset.day]||[];byDay[s.dataset.day].push(`${s.dataset.k}: ${s.value}`);}});Object.keys(byDay).forEach(d=>txt+=`Día ${d} — ${byDay[d].join(' · ')}\n`);document.getElementById('itinSummary').innerText=any?txt:'Tu itinerario aparecerá acá a medida que lo armes.';}
function sendItinerary(){const i=document.getElementById('itinIn').value,o=document.getElementById('itinOut').value,pax=document.getElementById('itinPax').value||1;if(!i||!o){toast('Elegí las fechas de tu viaje primero');return;}const sels=[...document.querySelectorAll('#itinDays select')];let msg=`¡Hola Sineus Tour! Quiero armar este itinerario:%0a%0aLlegada: ${i}%0aSalida: ${o}%0aPasajeros: ${pax}%0a`;const byDay={};sels.forEach(s=>{if(s.value!=="—"){byDay[s.dataset.day]=byDay[s.dataset.day]||[];byDay[s.dataset.day].push(`${s.dataset.k}: ${s.value}`);}});Object.keys(byDay).forEach(d=>msg+=`%0aDía ${d}: ${byDay[d].join(' · ')}`);msg+=`%0a%0a¿Me ayudan a cerrarlo? ¡Gracias!`;window.open(`https://api.whatsapp.com/send?phone=${WA}&text=${msg}`,'_blank');}

/* ===== SHOP ===== */
let cart={},wish=new Set(),coupon=0,activeTab="todos";
document.getElementById('shopTabs').innerHTML=CATS.map((c,i)=>`<button class="${i===0?'active':''}" data-t="${c[0]}" data-i18n="cat_${c[0]}">${c[1]}</button>`).join('');
document.querySelectorAll('#shopTabs button').forEach(b=>b.onclick=()=>{activeTab=b.dataset.t;document.querySelectorAll('#shopTabs button').forEach(x=>x.classList.toggle('active',x===b));renderProducts();});
function P(id){return PRODUCTS.find(p=>p[0]===id);}
function stars(n){return '★★★★★'.slice(0,n)+'☆☆☆☆☆'.slice(0,5-n);}
function renderProducts(){const q=(document.getElementById('shopSearch').value||'').toLowerCase();const items=PRODUCTS.filter(p=>(activeTab==="todos"||p[1]===activeTab)&&(p[4].toLowerCase().includes(q)||p[2].toLowerCase().includes(q)));
  document.getElementById('productGrid').innerHTML=items.map(p=>`<article class="card"><div class="thumb" style="background:${thumbBg(p[1])}"><span class="cat">${p[2]}</span><button class="wish ${wish.has(p[0])?'on':''}" onclick="toggleWish('${p[0]}')" aria-label="Favorito"><svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><path d="M12 21l-1.5-1.3C5 14.7 2 12 2 8.5 2 6 4 4 6.5 4 8 4 9.5 4.8 12 7c2.5-2.2 4-3 5.5-3C20 4 22 6 22 8.5c0 3.5-3 6.2-8.5 11.2z"/></svg></button></div><div class="card-body"><h4>${p[4]}</h4><div class="stars" style="color:var(--gold)">${stars(p[6])}</div><p class="blurb">${p[7]}</p><div class="price-row"><span class="price">USD ${p[5]}</span><button class="add" data-add="${p[0]}" data-i18n="add">+ Agregar</button></div></div></article>`).join('')||'<p style="color:var(--ink-soft)">Sin resultados.</p>';
  document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{addCart(b.dataset.add);b.classList.add('added');b.textContent=t('added');setTimeout(()=>{b.classList.remove('added');b.textContent=t('add');},1000);});}
function thumbBg(c){return {vinos:'linear-gradient(150deg,#efe2d4,#dcc6a8)',remeras:'linear-gradient(150deg,#e4e7d3,#c8cfa8)',bolsos:'linear-gradient(150deg,#ecd9c8,#d6b393)',maletas:'linear-gradient(150deg,#e2e6d2,#c4cda0)',cueros:'linear-gradient(150deg,#ecd6c0,#cfa87f)',souvenirs:'linear-gradient(150deg,#e9e3d0,#d3c79f)'}[c]||'var(--beige)';}
document.getElementById('packs').innerHTML=PACKS.map(p=>`<div class="pack"><span class="eyebrow" data-i18n="pack_label">Pack</span><h4 style="margin-top:8px">${p[0]}</h4><p style="color:var(--ink-soft);font-size:14px">${p[1]}</p><div class="pp">USD ${p[2]}</div><button class="btn btn-gold" onclick="reservar('${p[0]}')" data-i18n="pack_btn">Lo quiero</button></div>`).join('');
function addCart(id){cart[id]=(cart[id]||0)+1;updCart();renderCart();toast(`<b>Agregado</b> · ${P(id)[4]}`);}
function chQty(id,d){cart[id]=(cart[id]||0)+d;if(cart[id]<=0)delete cart[id];updCart();renderCart();}
function rmCart(id){delete cart[id];updCart();renderCart();}
function cartQty(){return Object.values(cart).reduce((a,b)=>a+b,0);}
function cartSub(){return Object.entries(cart).reduce((s,[id,q])=>s+P(id)[5]*q,0);}
function updCart(){const q=cartQty();const cc=document.getElementById('cartCount');cc.style.display=q?'grid':'none';cc.textContent=q;const sub=cartSub(),disc=Math.round(sub*coupon);document.getElementById('subLine').lastElementChild.textContent='USD '+sub;const dl=document.getElementById('discLine');if(coupon>0){dl.style.display='flex';dl.lastElementChild.textContent='-USD '+disc;}else dl.style.display='none';document.getElementById('cartTotal').textContent='USD '+(sub-disc);renderCartSuggest();}
function renderCart(){const c=document.getElementById('cartItems');const ids=Object.keys(cart);if(!ids.length){c.innerHTML='<div class="empty">Tu carrito está vacío.<br>Sumá productos mendocinos para empezar.</div>';return;}c.innerHTML=ids.map(id=>{const p=P(id),q=cart[id];return `<div class="ci"><div class="ci-thumb">${p[3]}</div><div class="ci-info"><span class="ci-cat">${p[2]}</span><b>${p[4]}</b><div class="qty"><button onclick="chQty('${id}',-1)">−</button><span>${q}</span><button onclick="chQty('${id}',1)">+</button></div><br><button class="ci-remove" onclick="rmCart('${id}')">Quitar</button></div><div class="ci-price">USD ${p[5]*q}</div></div>`;}).join('');}
function applyCoupon(){const v=(document.getElementById('couponInput').value||'').trim().toUpperCase();if(v==='MENDOZA10'){coupon=.10;toast('<b>Cupón aplicado</b> · 10% off');}else{coupon=0;toast('Cupón no válido');}updCart();}
function checkout(m){if(!cartQty()){toast('Tu carrito está vacío');return;}toast(`<b>Demo:</b> redirigiría a ${m}`);}
function checkoutWA(){if(!cartQty()){toast('Tu carrito está vacío');return;}let msg='¡Hola Sineus Tour! Quiero este pedido de la tienda:%0a%0a';Object.entries(cart).forEach(([id,q])=>{const p=P(id);msg+=`• ${q}x ${p[4]} — USD ${p[5]*q}%0a`;});const sub=cartSub(),disc=Math.round(sub*coupon);if(disc)msg+=`%0aDescuento: -USD ${disc}`;msg+=`%0aTotal: USD ${sub-disc}%0a%0a¿Me pasan disponibilidad y forma de pago?`;window.open(`https://api.whatsapp.com/send?phone=${WA}&text=${msg}`,'_blank');}

/* ===== WISHLIST ===== */
function toggleWish(id){if(wish.has(id))wish.delete(id);else{wish.add(id);toast(`<b>♥</b> Guardado en favoritos`);}updWish();renderProducts();renderWish();}
function updWish(){const wc=document.getElementById('wishCount');wc.style.display=wish.size?'grid':'none';wc.textContent=wish.size;}
function renderWish(){const c=document.getElementById('wishItems');if(!wish.size){c.innerHTML='<div class="empty">Todavía no tenés favoritos.<br>Tocá el ♥ en cualquier producto.</div>';return;}c.innerHTML=[...wish].map(id=>{const p=P(id);return `<div class="ci"><div class="ci-thumb">${p[3]}</div><div class="ci-info"><span class="ci-cat">${p[2]}</span><b>${p[4]}</b><br><button class="ci-remove" onclick="toggleWish('${id}')">Quitar</button> · <button class="ci-remove" onclick="addCart('${id}')">Agregar al carrito</button></div><div class="ci-price">USD ${p[5]}</div></div>`;}).join('');}

/* ===== CONTACT / NEWSLETTER / RESERVAR ===== */
function sendContact(){const n=document.getElementById('cNombre').value,a=document.getElementById('cApellido').value,t=document.getElementById('cTel').value,e=document.getElementById('cEmail').value,tipo=document.getElementById('cTipo').value,m=document.getElementById('cMsg').value;if(!n||!e){toast('Completá al menos nombre y email');return;}const body=`Nombre: ${n} ${a}%0D%0ATeléfono: ${t}%0D%0AEmail: ${e}%0D%0AQuiere cotizar: ${tipo}%0D%0A%0D%0A${m}`;window.location.href=`mailto:turismosineus@gmail.com?subject=Consulta web - ${n} ${a}&body=${body}`;}
function subscribe(){const e=document.getElementById('newsEmail').value;if(!e||!e.includes('@')){toast('Ingresá un email válido');return;}document.getElementById('newsEmail').value='';toast('<b>¡Listo!</b> Te suscribiste al newsletter');}
function reservar(x){const msg=`¡Hola Sineus Tour! Me interesa reservar: ${x}. ¿Me pasan info y disponibilidad?`;window.open(`https://api.whatsapp.com/send?phone=${WA}&text=${encodeURIComponent(msg)}`,'_blank');}

/* ===== DRAWERS / DARK / TOAST ===== */
function openCart(){renderCart();document.getElementById('cart').classList.add('open');document.getElementById('scrim').classList.add('open');}
function openWish(){renderWish();document.getElementById('wish').classList.add('open');document.getElementById('scrim').classList.add('open');}
function closeAll(){document.querySelectorAll('.drawer').forEach(d=>d.classList.remove('open'));document.getElementById('scrim').classList.remove('open');}
function toggleDark(){document.body.classList.toggle('dark');}
let tt2;let payMethod='tarjeta';
function suggestProducts(n){var out=[];for(var i=0;i<PRODUCTS.length&&out.length<n;i++){if(!cart[PRODUCTS[i][0]])out.push(PRODUCTS[i]);}return out;}
function csHTML(cb){var list=suggestProducts(2);if(!list.length)return '';return '<div class="cs-title" data-i18n="cs_title">También te puede interesar</div>'+list.map(function(p){return '<div class="cs-item"><span class="cs-ic">'+p[3]+'</span><div class="cs-info"><b>'+p[4]+'</b><span>USD '+p[5]+'</span></div><button class="cs-add" onclick="addCart(\''+p[0]+'\')'+(cb||'')+'" aria-label="Agregar">+</button></div>';}).join('');}
function renderCartSuggest(){var el=document.getElementById('cartSuggest');if(!el)return;el.innerHTML=cartQty()?csHTML(''):'';if(window.applyI18n)applyI18n(el);}
function openCheckout(){if(!cartQty()){toast('Tu carrito está vacío');return;}renderCheckout();setPay('tarjeta');var c=document.getElementById('checkout');c.classList.add('open');c.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';}
function closeCheckout(){var c=document.getElementById('checkout');c.classList.remove('open');c.setAttribute('aria-hidden','true');document.body.style.overflow='';}
function renderCheckout(){var sub=cartSub(),disc=Math.round(sub*coupon),tot=sub-disc;
 document.getElementById('coItems').innerHTML=Object.entries(cart).map(function(e){var p=P(e[0]),q=e[1];return '<div class="co-item"><span class="co-item-ic">'+p[3]+'</span><div class="co-item-i"><b>'+p[4]+'</b><span>'+q+' \u00d7 USD '+p[5]+'</span></div><span class="co-item-p">USD '+(p[5]*q)+'</span></div>';}).join('');
 document.getElementById('coSub').textContent='USD '+sub;
 var dl=document.getElementById('coDiscLine');if(disc>0){dl.style.display='flex';document.getElementById('coDisc').textContent='-USD '+disc;}else{dl.style.display='none';}
 document.getElementById('coTotal').textContent='USD '+tot;document.getElementById('coPayAmt').textContent='USD '+tot;
 document.getElementById('coSuggest').innerHTML=csHTML(';renderCheckout()');}
function setPay(m){payMethod=m;document.querySelectorAll('.co-pay-tabs button').forEach(function(b){b.classList.toggle('on',b.dataset.pay===m);});var body=document.getElementById('coPayBody');if(!body)return;if(m==='tarjeta'){body.innerHTML='<p>Pag\u00e1s con tarjeta de cr\u00e9dito o d\u00e9bito. Al confirmar, se abre el formulario seguro de <b>KamiPay</b> para cargar los datos de tu tarjeta.</p><div class="co-cards">VISA \u00b7 Mastercard \u00b7 Amex</div>';}else{body.innerHTML='<p>Al confirmar, <b>KamiPay</b> genera un c\u00f3digo <b>PIX</b> para pagar al instante desde tu banco (ideal para clientes de Brasil).</p>';}}
function payKami(){if(!cartQty()){toast('Tu carrito est\u00e1 vac\u00edo');return;}var m=payMethod==='pix'?'PIX':'tarjeta';closeCheckout();cart={};updCart();renderCart();toast('<b>\u00a1Gracias!</b> Pedido recibido (demo). En producci\u00f3n, KamiPay procesa el pago con '+m+'.');}
function toast(h){const t=document.getElementById('toast');t.innerHTML=h;t.classList.add('show');clearTimeout(tt2);tt2=setTimeout(()=>t.classList.remove('show'),2400);}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeAll();closeVideo();}});

