function applyI18n(root){root=root||document;
  (root.querySelectorAll?root.querySelectorAll('[data-i18n]'):[]).forEach(el=>{const v=I18N[LANG][el.getAttribute('data-i18n')];if(v!=null)el.textContent=v;});
  (root.querySelectorAll?root.querySelectorAll('[data-i18n-ph]'):[]).forEach(el=>{const v=I18N[LANG][el.getAttribute('data-i18n-ph')];if(v!=null)el.setAttribute('placeholder',v);});
}
function setLang(l){if(!I18N[l])return;LANG=l;document.documentElement.lang=l;document.querySelectorAll('.lang-flag').forEach(b=>b.classList.toggle('on',b.dataset.l===l));applyI18n();try{localStorage.setItem('sineus_lang',l)}catch(e){}}
new MutationObserver(ms=>{ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===1){if(n.hasAttribute&&n.hasAttribute('data-i18n')){const v=I18N[LANG][n.getAttribute('data-i18n')];if(v!=null)n.textContent=v;}applyI18n(n);}}));}).observe(document.body,{childList:true,subtree:true});
(function(){let l='es';try{l=localStorage.getItem('sineus_lang')||'es'}catch(e){}setLang(l);})();

