var EXPDETAIL={"vin": {"img": "var(--img1)", "tag": "Vinícolas", "title": "Experiencias en bodegas", "lead": "Diseñamos tu día entre viñedos: elegís las bodegas que más te gustan y nosotros coordinamos reservas, traslados y tiempos para que solo tengas que disfrutar.", "includes": ["Traslado ida y vuelta desde tu alojamiento", "Reserva y coordinación en las bodegas", "Degustaciones guiadas", "Opción de almuerzo o cena maridada", "Atención personalizada en español y portugués"]}, "alta": {"img": "var(--img6)", "tag": "Aventura", "title": "Alta Montaña", "lead": "Un día inolvidable por la Cordillera de los Andes: Potrerillos, Uspallata, Puente del Inca y la vista al imponente Aconcagua.", "includes": ["Traslado en vehículo habilitado por turismo", "Guía durante todo el recorrido", "Paradas en los principales miradores", "Agua mineral a bordo"]}, "lenas": {"img": "var(--img7)", "tag": "Nieve", "title": "Las Leñas", "lead": "Vivís un día en uno de los centros de esquí más importantes de Sudamérica, con montañas nevadas y actividades para toda la familia.", "includes": ["Traslado ida y vuelta", "Día en el centro de esquí", "Asistencia de nuestro equipo", "Recomendaciones de alquiler de equipo"]}, "raft": {"img": "var(--img8)", "tag": "Adrenalina", "title": "Rafting", "lead": "Descenso por los rápidos del Río Mendoza con guías especializados y todo el equipo de seguridad, rodeado de paisajes increíbles.", "includes": ["Equipo completo (casco, chaleco y remo)", "Guías especializados", "Briefing de seguridad", "Traslado opcional"]}, "cab": {"img": "var(--img9)", "tag": "A caballo", "title": "Cabalgatas", "lead": "Recorré viñedos y montañas a caballo. Elegís la zona donde querés cabalgar y te mostramos las opciones disponibles.", "includes": ["Caballos y guía baqueano", "Recorrido según tu nivel", "Distintas zonas a elección", "Fotos del paseo"]}, "sraf": {"img": "var(--img10)", "tag": "Sur", "title": "San Rafael & Cañón del Atuel", "lead": "El oasis del sur mendocino: Villa 25 de Mayo, el Dique El Nihuil, el espectacular Cañón del Atuel y las actividades de Valle Grande.", "includes": ["Recorrido de día completo", "Traslado y coordinación", "Paradas panorámicas", "Opciones de aventura en Valle Grande"]}};
function openExp(k){var d=EXPDETAIL[k];if(!d)return;
  var wa='https://wa.me/5492615451540?text='+encodeURIComponent('¡Hola Sineus! Me interesa la experiencia: '+d.title+'. ¿Me pasan información y disponibilidad?');
  var inc=d.includes.map(function(x){return '<li>'+x+'</li>';}).join('');
  var el=document.getElementById('expPage');
  el.innerHTML='<div class="exp-page-bar"><button class="exp-back" onclick="closeExp()">\u2190 Volver</button></div>'+
    '<div class="exp-hero" style="background-image:'+d.img+'"><div class="exp-hero-in"><span class="tag">'+d.tag+'</span><h2>'+d.title+'</h2></div></div>'+
    '<div class="wrap exp-body"><p class="exp-lead">'+d.lead+'</p><h3>Qué incluye</h3><ul class="exp-inc">'+inc+'</ul>'+
    '<div class="exp-cta"><a class="btn btn-primary" target="_blank" rel="noopener" href="'+wa+'">Reservar por WhatsApp</a><button class="btn btn-ghost" onclick="closeExp()">Volver</button></div>'+
    '<p class="exp-note">Las experiencias pueden variar según la temporada y la disponibilidad. Confirmá los detalles al momento de reservar.</p></div>';
  el.classList.add('open');el.setAttribute('aria-hidden','false');el.scrollTop=0;document.body.style.overflow='hidden';}
function closeExp(){var el=document.getElementById('expPage');el.classList.remove('open');el.setAttribute('aria-hidden','true');document.body.style.overflow='';}
function playBem(){var v=document.getElementById('bemVideo'),p=document.getElementById('bemPlay');if(v){try{v.play();}catch(e){}p&&p.classList.add('hide');}}
document.addEventListener('DOMContentLoaded',function(){
  var v=document.getElementById('bemVideo'),fr=document.getElementById('bemFrame'),p=document.getElementById('bemPlay');
  if(v&&fr){v.setAttribute('preload','metadata');v.setAttribute('controls','');fr.insertBefore(v,p);
    v.addEventListener('play',function(){p&&p.classList.add('hide');});
    v.addEventListener('pause',function(){if(!v.ended){p&&p.classList.remove('hide');}});}
  var vm=document.getElementById('vmodal');if(vm){vm.style.display='none';}
});

