(function(){
var VIEWS={home:['inicio','trust','testi','servicios','bienvenida'],experiencias:['experiencias','combos'],faq:['faq'],bodegas:['vinicolas'],altamontana:['altamontana'],aventura:['aventura'],sanrafael:['sanrafael'],novedades:['novedades'],itinerario:['itinerario'],tienda:['tienda'],contacto:['contacto']};
var ALL=['inicio','trust','testi','bienvenida','experiencias','combos','servicios','faq','vinicolas','altamontana','aventura','sanrafael','novedades','itinerario','tienda','contacto'];
var DETAIL=['bodegas','altamontana','aventura','sanrafael'];
window.showView=function(v,anchor){
  if(!VIEWS[v])v='home';
  ALL.forEach(function(id){var el=document.getElementById(id);if(el){el.style.display=VIEWS[v].indexOf(id)>=0?'':'none';}});
  VIEWS[v].forEach(function(id){var el=document.getElementById(id);if(el){el.querySelectorAll('.reveal').forEach(function(r){r.style.opacity='1';r.style.transform='none';});}});
  var sb=document.getElementById('subbar');if(sb){sb.style.display=DETAIL.indexOf(v)>=0?'':'none';}
  try{history.replaceState(null,'',v==='home'?location.pathname:'#'+v);}catch(e){}
  if(anchor){var a=document.getElementById(anchor);if(a){a.scrollIntoView({behavior:'smooth',block:'start'});return;}}
  window.scrollTo(0,0);
};
var MAPX={vin:'bodegas',alta:'altamontana',lenas:'aventura',raft:'aventura',cab:'aventura',sraf:'sanrafael'};
window.openExp=function(k){showView(MAPX[k]||'experiencias');};
window.bodInfo=function(k,ix){var r=(typeof REGIONS!=='undefined')?REGIONS[k]:null;if(!r)return;var bd=r.bd;if(typeof actFilter!=='undefined'&&actFilter!=='todas'){bd=bd.filter(function(b){return b[2].indexOf(actFilter)>=0;});}var b=bd[ix];if(!b)return;var el=document.getElementById('bodDetail');if(!el)return;el.innerHTML='<div class="bod-card"><b>'+b[0]+'</b><span class="bd-zone">'+r.name+'</span><p>Experiencias: '+b[2].join(', ')+'.</p><p class="bd-note">Consultá disponibilidad, horarios y valores al momento de reservar.</p></div>';};
function initView(){var h=(location.hash||'').replace('#','');showView(VIEWS[h]?h:'home');}
if(document.readyState!=='loading'){initView();}else{document.addEventListener('DOMContentLoaded',initView);}
})();